import{U as e,W as t,nt as n,t as r}from"./chunks/framework.BPwQCpO3.js";var i=JSON.parse(`{"title":"Groq (BYOK Provider)","description":"","frontmatter":{"title":"Groq (BYOK Provider)"},"headers":[],"relativePath":"providers/groq.md","filePath":"providers/groq.md"}`),a={name:`providers/groq.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="groq-mode-byok" tabindex="-1">Groq (Mode BYOK) <a class="header-anchor" href="#groq-mode-byok" aria-label="Permalink to “Groq (Mode BYOK)”">​</a></h1><p><strong>Groq</strong> adalah penyedia inference yang terkenal berkat hardware <strong>LPU</strong>-nya — keunggulan utamanya bukan kualitas model, tapi <strong>kecepatan</strong>: token mengalir puluhan kali lebih cepat dari rata-rata penyedia lain, sehingga jawaban terasa mengalir hampir seketika. Untuk chat dan <em>roleplay</em> yang responsif, ini pengalaman yang sulit ditandingi. Groq menjalankan model <em>open-weight</em> pilihan orang lain (Llama, GPT-OSS, Qwen, Whisper) — jadi kamu tidak membayar lisensi model, melainkan se<strong>wa</strong> mesin tercepatnya. Kalau kamu baru mengenal BYOK, baca dulu <a href="./../byok/">Pengenalan BYOK</a>.</p><div class="warning custom-block"><p class="custom-block-title">📅 Info penting 2026</p><p>Daftar model, angka rate limit, dan harga Groq berubah cukup sering — dan model berlabel <em>Preview</em> bisa <strong>dihentikan mendadak</strong>. Halaman ini mengajarkan <strong>cara</strong> yang benar, bukan daftar angka. Cek halaman resmi <a href="https://console.groq.com/docs/rate-limits" target="_blank" rel="noreferrer">rate limits Groq</a> dan <a href="https://groq.com/pricing/" target="_blank" rel="noreferrer">pricing Groq</a> sebelum menetapkan budget.</p></div><hr><h2 id="membuat-api-key" tabindex="-1">Membuat API Key <a class="header-anchor" href="#membuat-api-key" aria-label="Permalink to “Membuat API Key”">​</a></h2><ol><li>Daftar di <a href="https://console.groq.com" target="_blank" rel="noreferrer">console.groq.com</a> dengan email atau Google.</li><li>Buka menu <strong>API Keys</strong>.</li><li>Klik <strong>Create API Key</strong>, beri nama, lalu salin key yang ditampilkan.</li></ol><div class="danger custom-block"><p class="custom-block-title">🔒 Key only ditampilkan SEKALI</p><p>Seperti Gemini dan Claude, key Groq hanya ditampilkan <strong>satu kali</strong> saat pembuatan. Salin langsung ke tempat aman (password manager) sebelum menutup dialog — kalau hilang, satu-satunya jalan adalah <strong>membuat key baru</strong>. Jangan pernah menempelkan key ke chat, forum, atau screenshot.</p></div><hr><h2 id="mengaktifkan-groq-di-mikazuki-ai" tabindex="-1">Mengaktifkan Groq di Mikazuki AI <a class="header-anchor" href="#mengaktifkan-groq-di-mikazuki-ai" aria-label="Permalink to “Mengaktifkan Groq di Mikazuki AI”">​</a></h2><p>Ikuti alur BYOK standar dari panduan <a href="./../byok/instalasi.html">Instalasi &amp; Aktivasi</a>. Ringkasannya untuk Groq:</p><ol><li>Buka <strong>Settings → Engine</strong>, pilih mode <strong>BYOK</strong>.</li><li>Pada pilihan provider, pilih <strong>Groq</strong>.</li><li>Tempel API key yang barusan kamu buat.</li><li>Klik tombol 🔍 <strong>fetch models</strong> — daftar model akan muncul otomatis dari key kamu.</li><li>Pilih model, atur <a href="./../byok/parameter-dasar.html">Parameter Dasar</a> — terutama <code>context_window</code> dan <code>max_tokens</code> — lalu klik simpan.</li></ol><p>Worker Mikazuki memakai <strong>provider native Groq</strong> dengan <strong>endpoint tetap (fixed)</strong>, jadi tidak ada kolom <em>Base URL</em> yang perlu kamu isi. Sebagai referensi, API Groq berformat <em>OpenAI-compatible</em> di <code>https://api.groq.com/openai/v1</code> — tapi tetap pilih provider <strong>Groq</strong> di Mikazuki, bukan jalur <em>OpenAI Compatible</em> manual.</p><div class="tip custom-block"><p class="custom-block-title">Sudah baik dari sananya</p><p>Default <strong>temperature 0.85</strong> Mikazuki sudah dipetakan dengan baik untuk roleplay; kamu tidak perlu mengubahnya kecuali memang ingin gaya jawaban yang sangat berbeda.</p></div><p>Kecepatan streaming Groq biasanya langsung terasa di pesan pertama — kalau kamu terbiasa menunggu token muncul pelan di provider lain, ini bagian yang paling memuaskan.</p><hr><h2 id="free-tier-harga" tabindex="-1">Free Tier &amp; Harga <a class="header-anchor" href="#free-tier-harga" aria-label="Permalink to “Free Tier &amp; Harga”">​</a></h2><p>Groq punya model gratis yang berbeda dari kebanyakan provider lain:</p><ul><li><strong>Benar-benar gratis, tanpa kartu kredit</strong> — tidak ada sistem kredit, tidak ada saldo top-up, tidak ada token per-percobaan.</li><li><strong>Tidak ada billing per-token di free tier</strong>: semua model bisa diakses, pembatasnya <strong>hanya rate limit</strong> (lihat bagian berikutnya).</li><li>Ini berbeda dari DeepSeek (model top-up balance) atau Mistral (experiment plan berbatas waktu) — di Groq kamu bisa langsung chat tanpa pernah mengisi apa pun.</li></ul><div class="warning custom-block"><p class="custom-block-title">⚠️ Gratis bukan untuk produksi</p><p>Free tier Groq dirancang untuk <strong>prototyping dan pemakaian pribadi</strong> — di situlah tempatnya untuk Mikazuki. Untuk beban produksi (aplikasi publik, banyak pengguna), anggap ini bukan fondasi yang layak: limitnya ketat dan bisa habis dalam hitungan menit pemakaian intensif.</p></div><p>Kalau suatu saat butuh limit lebih besar: tier berbayar mulai <strong>Developer</strong>, dengan harga per juta token mulai dari beberapa sen dolar untuk model termurah. Jangan kunci angka — cek <a href="https://groq.com/pricing/" target="_blank" rel="noreferrer">pricing resmi Groq</a> untuk tarif terkini.</p><hr><h2 id="rate-limit" tabindex="-1">Rate Limit <a class="header-anchor" href="#rate-limit" aria-label="Permalink to “Rate Limit”">​</a></h2><p>Rate limit Groq punya bentuk yang khas — penting dipahami sebelum kamu kaget kena 429:</p><ul><li><strong>Diukur per model</strong>: setiap model punya angka sendiri, bukan satu kuota gabungan.</li><li><strong>Volameter metrik: RPM</strong> (request per menit), <strong>RPD</strong> (request per hari), <strong>TPM</strong> (token per menit), <strong>TPD</strong> (token per hari) — untuk meta audio: <strong>ASH</strong> (audio seconds per hour) dan <strong>ASD</strong> (audio seconds per day).</li><li><strong>Berlaku di level Organization</strong>: menambah key baru <strong>tidak</strong> menaikkan limit — semua key di organisasi yang sama berbagi kuota.</li><li><strong>Cached tokens tidak dihitung</strong> ke rate limit — token yang dibaca dari cache tidak memakan TPM/TPD-mu.</li><li>Respons <strong>429</strong> menyertakan header <code>retry-after</code> (detik) serta header <code>x-ratelimit-*</code> — informasi kapan limit ter-reset tersedia langsung di respons.</li></ul><p><strong>Contoh dari tabel resmi</strong> (angka bisa berubah — ini hanya snapshot): <code>openai/gpt-oss-120b</code> = 30 RPM, 1.000 RPD, 8K TPM, 200K TPD.</p><div class="warning custom-block"><p class="custom-block-title">⚠️ Sumber pihak ketiga saling bertabrakan</p><p>Soal <strong>kuota harian agregat</strong>, sumber komunitas berbeda-beda — ada yang menulis sekitar 14.400 RPD, ada yang sekitar 1.000 RPD. Kami sengaja <strong>tidak</strong> mencantumkan angka agregat di sini; satu-satunya cara melihat limit pasti yang berlaku untukmu adalah <strong>console Groq → Settings (Limit)</strong>.</p></div><hr><h2 id="tier-free-developer-enterprise" tabindex="-1">Tier: Free, Developer, Enterprise <a class="header-anchor" href="#tier-free-developer-enterprise" aria-label="Permalink to “Tier: Free, Developer, Enterprise”">​</a></h2><ul><li><strong>Free</strong> — tanpa kartu kredit, rate limit ketat per model, cukup untuk mencoba dan chat pribadi.</li><li><strong>Developer</strong> — upgrade dengan menambahkan kartu (tanpa minimum spend). Rate limit naik sekitar <strong>~10x lipat</strong> dan tarif per token berkurang sekitar <strong>~25%</strong> <em>(angka ini per sumber pihak ketiga — verifikasi di console Groq sebelum mengandalkannya)</em>.</li><li><strong>Enterprise</strong> — untuk kebutuhan custom dan skala besar; bukan target pengguna Mikazuki pribadi.</li></ul><hr><h2 id="model-peringatan-preview" tabindex="-1">Model &amp; Peringatan Preview <a class="header-anchor" href="#model-peringatan-preview" aria-label="Permalink to “Model &amp; Peringatan Preview”">​</a></h2><p>Model di Groq semuanya <strong>open-weight</strong> — keluarga yang kemungkinan besar kamu temui di daftar fetch models:</p><ul><li><strong>GPT-OSS</strong> — <code>gpt-oss-...</code>, flagship open-weight OpenAI di Groq.</li><li><strong>Llama</strong> — <code>llama-...</code>, pilihan klasik Meta.</li><li><strong>Qwen</strong> — <code>qwen...</code>, alternatif open-weight dari Alibaba.</li><li><strong>Whisper</strong> — model audio untuk transkripsi.</li></ul><p>Ambil nama model <strong>persis dari daftar fetch models Mikazuki</strong> — ketik manual mudah salah ejaan atau salah suffix versi.</p><div class="danger custom-block"><p class="custom-block-title">⚠️ Model Preview bisa hilang mendadak</p><p>Groq secara resmi menyatakan model berlabel <strong>Preview</strong> bisa <strong>dihentikan kapan saja</strong> di akhir hari. Jangan kaget kalau model favoritmu tiba-tiba menghilang dari daftar — ini perilaku yang diumumkan sendiri oleh Groq, bukan bug Mikazuki. Solusinya: refetch models, lalu pindah ke model tetangga yang tersedia.</p></div><hr><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to “Troubleshooting”">​</a></h2><details class="details custom-block"><summary>Error 429 begitu cepat</summary><p>Rate limit free tier Groq memang <strong>ketat dan per model</strong> — 429 muncul paling cepat di sini dibanding provider lain. Cek header <code>retry-after</code> di respons untuk tahu berapa lama menunggu, kurangi panjang percakapan (<em>prune</em> konteks lama agar TPM/TPD tidak cepat habis), atau sisipkan tier <strong>Developer</strong> kalau pemakaianmu memang intensif.</p></details><details class="details custom-block"><summary>Error 404 / invalid model</summary><p>Dua kemungkinan: nama model salah eja, <strong>atau</strong> model <em>Preview</em>-nya sudah dinonaktifkan Groq (lihat peringatan di atas). Langkah pertama selalu: klik 🔍 <strong>fetch models</strong> ulang di Mikazuki dan pakai nama dari daftar terbaru — jangan berharap nama lama masih hidup.</p></details><details class="details custom-block"><summary>Jawaban terpotong</summary><p>Angka <code>max_tokens</code> di <a href="./../byok/parameter-dasar.html">Parameter Dasar</a> mungkin terlalu kecil — model berhenti sebelum sempat menulis panjang. Naikkan nilainya, tapi ingat <code>max_tokens</code> ikut dipotong dari <code>context_window</code>, jadi jangan set berlebihan tanpa menaikkan <code>context_window</code> juga.</p></details><details class="details custom-block"><summary>Error 401 / key invalid</summary><p>Key Groq <strong>hanya ditampilkan sekali</strong> saat pembuatan — kalau kamu tidak yakin sudah menyimpannya dengan benar, buat <strong>key baru</strong> dari menu <strong>API Keys</strong> di <a href="https://console.groq.com" target="_blank" rel="noreferrer">console.groq.com</a> dan tempel ulang di Settings Mikazuki. Pastikan juga tidak ada spasi yang ikut tersalin.</p></details><hr><h2 id="jelajahi-byok-lebih-lanjut" tabindex="-1">Jelajahi BYOK Lebih Lanjut <a class="header-anchor" href="#jelajahi-byok-lebih-lanjut" aria-label="Permalink to “Jelajahi BYOK Lebih Lanjut”">​</a></h2><ul><li><a href="./../byok/">Pengenalan BYOK</a> — konsep dasar dan cara kerjanya.</li><li><a href="./../byok/instalasi.html">Instalasi &amp; Aktivasi</a> — langkah menyalakan mode BYOK.</li><li><a href="./../byok/parameter-dasar.html">Parameter Dasar</a> — atur <code>max_tokens</code>, <code>context_window</code>, dan parameter kreativitas.</li><li><a href="./gemini.html">Google Gemini</a> — panduan padanan untuk provider Gemini.</li><li><a href="./deepseek.html">DeepSeek</a> — panduan padanan untuk provider top-up.</li><li><a href="./systemai.html">System AI</a> — kalau kamu tidak ingin mengurus key dan pembayaran API sendiri.</li></ul>`,44)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};